// Stop with a clear error until Config is filled in. Get the IDs with /ids in each topic.
const c = $json;
const missing = ['group_chat_id', 'bluesky_topic_id', 'mastodon_topic_id'].filter((k) => !/^-?\d+$/.test(String(c[k] || '')));
if (missing.length) throw new Error(`Fill in Config: ${missing.join(', ')}. Send /ids in each topic of the Telegram group to get the values.`);
return [{ json: c }];

// New replies, mentions, and quotes since the last run, oldest first.
// The first run looks back one hour. Likes, reposts, and follows are not forwarded.
const s = $('Bluesky session').first().json;
if (!s.did) throw new Error('Bluesky login failed: ' + JSON.stringify(s.error || s).slice(0, 300));
if ($json.error) throw new Error('Bluesky notifications failed: ' + JSON.stringify($json.error).slice(0, 300));
const sd = $getWorkflowStaticData('global');
const since = sd.bluesky_since || new Date(Date.now() - 3600e3).toISOString();
const list = $json.notifications || [];
sd.bluesky_since = list.reduce((m, n) => (n.indexedAt > m ? n.indexedAt : m), since);
const picked = list
  .filter((n) => ['reply', 'mention', 'quote'].includes(n.reason) && n.indexedAt > since && n.author.did !== s.did)
  .reverse();
if (!picked.length) return [];
// The post each notification answers or quotes, for context.
const about = (n) => {
  const e = (n.record || {}).embed || {};
  if (n.reason === 'quote') return (e.record && (e.record.uri || (e.record.record || {}).uri)) || '';
  return ((n.record || {}).reply || {}).parent?.uri || '';
};
const parents = [...new Set(picked.map(about).filter(Boolean))].slice(0, 25);
return [{ json: { picked: picked.map((n) => ({ ...n, about: about(n) })), parents } }];

// One Telegram message per notification, for the Bluesky topic.
// The "Open on Bluesky" link is how a reply in Telegram finds its target: keep it in the message.
const cfg = $('Config').first().json;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const clip = (s, n) => (s.length > n ? s.slice(0, n - 3) + '...' : s);
const texts = Object.fromEntries(($json.posts || []).map((p) => [p.uri, (p.record || {}).text || '']));
const VERB = { reply: 'replied', mention: 'mentioned you', quote: 'quoted you' };
return $('Pick Bluesky').first().json.picked.map((n) => {
  const link = `https://bsky.app/profile/${n.author.did}/post/${n.uri.split('/').pop()}`;
  const embed = String(((n.record || {}).embed || {}).$type || '');
  const media = /images|video/.test(embed) ? '\n[media: open the post to see it]' : '';
  const re = texts[n.about];
  const html = `<b>${esc(n.author.displayName || n.author.handle)}</b> @${esc(n.author.handle)} ${VERB[n.reason]}:\n`
    + esc(clip((n.record || {}).text || '', 1500)) + media
    + (re ? `\n\nRe: <i>${esc(clip(re, 140))}</i>` : '')
    + `\n\n<a href="${link}">Open on Bluesky</a>`;
  return { json: { chat_id: cfg.group_chat_id, topic_id: cfg.bluesky_topic_id, html } };
});

// New mentions since the last run, oldest first. Replies to your posts arrive as mentions.
// The first run looks back one hour.
const items = $input.all().map((i) => i.json);
if (items[0] && items[0].error) throw new Error('Mastodon notifications failed: ' + JSON.stringify(items[0].error).slice(0, 300));
const sd = $getWorkflowStaticData('global');
const since = sd.mastodon_since || new Date(Date.now() - 3600e3).toISOString();
sd.mastodon_since = items.reduce((m, n) => (n.created_at > m ? n.created_at : m), since);
return items.filter((n) => n.type === 'mention' && n.status && n.created_at > since).reverse().map((n) => ({ json: n }));

// One Telegram message per mention, for the Mastodon topic.
// The "Open on Mastodon" link is how a reply in Telegram finds its target; #v= carries the visibility.
const cfg = $('Config').first().json;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const clip = (s, n) => (s.length > n ? s.slice(0, n - 3) + '...' : s);
const toText = (html) => String(html || '')
  .replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>\s*<p>/gi, '\n\n').replace(/<[^>]+>/g, '')
  .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&').trim();
const picked = $('Pick Mastodon').all();
return $input.all().map((item, i) => {
  const n = picked[i].json;
  const st = n.status;
  const parent = st.in_reply_to_id && !item.json.error ? toText(item.json.content) : '';
  const link = `https://mastodon.social/@${n.account.acct}/${st.id}#v=${st.visibility}`;
  const verb = st.in_reply_to_id ? 'replied' : 'mentioned you';
  const scope = st.visibility === 'public' ? '' : ` (${st.visibility === 'direct' ? 'private mention' : st.visibility})`;
  const media = (st.media_attachments || []).length ? '\n[media: open the post to see it]' : '';
  const html = `<b>${esc(n.account.display_name || n.account.username)}</b> @${esc(n.account.acct)} ${verb}${scope}:\n`
    + esc(clip(toText(st.content), 1500)) + media
    + (parent ? `\n\nRe: <i>${esc(clip(parent, 140))}</i>` : '')
    + `\n\n<a href="${link}">Open on Mastodon</a>`;
  return { json: { chat_id: cfg.group_chat_id, topic_id: cfg.mastodon_topic_id, html } };
});
